import heapq

def solve(n, roads):
    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Prim's algorithm to find MST
    visited = [False] * n
    min_heap = [(0, 0)]  # (cost, city)
    total_cost = 0

    while min_heap:
        cost, city = heapq.heappop(min_heap)
        if visited[city]:
            continue
        visited[city] = True
        total_cost += cost
        for neighbor, weight in graph[city]:
            if not visited[neighbor]:
                heapq.heappush(min_heap, (weight, neighbor))

    # Check if all cities are visited
    if all(visited):
        return total_cost
    else:
        return -1

def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm implementation
    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:  # avoid duplicates
                edges.append((w, u, v))

    # Sort edges by weight
    edges.sort()

    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
