def is_anagram(s, t):
    """
    Returns True if the characters of s appear in t in any order.
    input:
        s string of lowercase English letters
        t string of lowercase English letters
    output:
        bool is the string a anagram?
    """
    if len(s) != len(t): return False

    # dictionary of unique characters in t (excluding any characters contradicting the stuff in s)
    t_dict = {}
    for char in t:
        if char in s:
            if char in t_dict:
                t_dict[char] += 1
            else:
                t_dict[char] = 1

    # dictionary of s
    s_dict = {}
    for char in s:
        if char in s_dict:
            s_dict[char] += 1
        else:
            s_dict[char] = 1

    # check if the dictionaries have the same keys and values elements
    return s_dict == t_dict

