def solve(S):
    import numpy as np
    import scipy.signal

    def to_number(S):
        """ Convert a string of letters to a numpy array of numbers. """
        return np.array([ord(c) - ord('A') for c in S])

    def to_letters(A):
        """ Convert a numpy array of numbers to a string of letters. """
        return ''.join([chr(c + ord('A')) for c in A])

    def hamming_distance(A, B):
        """ Compute the Hamming distance between two numpy arrays. """
        return np.sum(np.abs(A - B))

    # Convert S to a numpy array of numbers, and compute all pairwise Hamming distances.
    S = to_number(S)
    D = np.zeros((len(S), len(S)))
    for i in range(len(S)):
        for j in range(len(S)):
            D[i, j] = hamming_distance(S[i:], S[j:])

    # Take the DFT of the Hamming distance matrix, and compute the maximum covariance.
    DFT = np.fft.fft2(D)
    max_covariance = np.argmax(np.abs(DFT))

    # Take the inverse DFT of the maximum covariance, and convert back to a string of letters.
    S2 = to_letters(np.fft.ifft2(DFT)[max_covariance])
    return S2

