def merge_sort(nums):
    if len(nums) <= 1:
        # Base case, since merge sort works on dividing the list into halves
        return 0, nums
    # Divide the list into two halves and sort them recursively
    mid = len(nums) // 2
    left_inversions, left_sorted = merge_sort(nums[:mid])
    right_inversions, right_sorted = merge_sort(nums[mid:])
    total_inversions = left_inversions + right_inversions

    # Count the inversions across two halves while merging
    i, j = 0, 0
    merged = []
    while i < len(left_sorted) and j < len(right_sorted):
        if left_sorted[i] <= right_sorted[j]:
            merged.append(left_sorted[i])
            i += 1
        else:
            merged.append(right_sorted[j])
            j += 1
            total_inversions += len(left_sorted) - i

    # Append any remaining elements from left and right halves
    if i < len(left_sorted):
        merged.extend(left_sorted[i:])
    if j < len(right_sorted):
        merged.extend(right_sorted[j:])
    return total_inversions, merged

