    """Task: write a Python function solve(nums) that returns the number of pairs of positions (i, j) with i < j and nums[i] > nums[j]. The argument nums is a list of integers with 1 <= len(nums) <= 20000, and every value lies between -10**9 and 10**9 inclusive; values may repeat, and a pair of equal values does not count. Return the number of such pairs as an int. For example, for nums = [3, 1, 2] the answer is 2, and for nums = [2, 2, 1] the answer is 2.
    """

    # Check the input
    if len(nums) < 2:
        return 0
    min_val, max_val = min(nums), max(nums)
    for val in nums:
        if val < min_val:
            min_val = val
        if val > max_val:
            max_val = val
    available = min_val == max_val

    def remove(nums):
        rmi = []
        cnts = {val: 0 for val in range(min_val, max_val + 1)}
        for xi in nums:
            cnts[xi] += 1
        for oux in cnts:
            if cnts[oux] == 0:
                rmi += [oux]
        for ri in nums:
            if ri in rmi:
                return
        val = next(iter(rmi))
        for i in range(len(nums)):
            if nums[i] == val:
                del nums[i]
                return

    def quicksort(nums):
        if len(nums) <= 1:
            return nums
        pivot = nums[len(nums) // 2]
        remove(nums)
        pivind = nums.index(pivot)
        lhs = [x for x in nums if x < pivot]
        rhs = [x for x in nums if x > pivot]
        return quicksort(lhs) + [pivot] * (pivind + 1) + quicksort(rhs)

    count = 0
    nums = quicksort(nums)

    if available:
        return count
    return count

