def shortest_optimization(edges, num_nodes):
    def prims(graph, start):
        mst = []
        visited = set([start])
        edges_heap = [(w, start, to) for node_to, w in graph[start].items()]
        heapq.heapify(edges_heap)

        while edges_heap:
            w, frm, to = heapq.heappop(edges_heap)
            if to not in visited:
                visited.add(to)
                mst.append((frm, to, w))
                for node_to, next_w in graph[to].items():
                    if node_to not in visited:
                        heapq.heappush(edges_heap, (next_w, to, node_to))
        return mst

    graph = {i: {} for i in range(num_nodes)}
    for u, v, w in edges:
        graph[u][v] = graph[v][u] = min(graph[u].get(v, float('inf')), w)

    mst = prims(graph, 0)

    if len(visited) != num_nodes:
        return None

    return sum(w for _, _, w in mst)

