class SegmentTreeNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.count = 0

def build_segment_tree(arr, l, r):
    node = SegmentTreeNode(l, r)
    if l == r:
        return node
    mid = (l + r) // 2
    node.left = build_segment_tree(arr, l, mid)
    node.right = build_segment_tree(arr, mid + 1, r)
    return node

def update_segment_tree(node, index, value):
    if node.l == node.r == index:
        node.count = 1
        return
    if value < node.left.r:
        update_segment_tree(node.left, index, value)
    else:
        update_segment_tree(node.right, index, value)
    node.count = node.left.count + node.right.count

def query_segment_tree(node, value):
    if node.r < value:
        return node.count
    if node.l == node.r:
        return 0
    if value <= node.left.r:
        return query_segment_tree(node.left, value)
    return query_segment_tree(node.left, value) + query_segment_tree(node.right, value)

