    if not nums:
        return 0
    unique_sorted = sorted(set(nums))
    mapping = {v: i for i, v in enumerate(unique_sorted)}
    size = len(unique_sorted)
    root = build_segment_tree(unique_sorted, 0, size - 1)
    result = 0
    for num in reversed(nums):
        idx = mapping[num]
        result += query_segment_tree(root, idx)
        update_segment_tree(root, idx, num)
    return result

