class SmartCountCounter(Counter[str]):
    """Subclasses ``collections.Counter`` to offer ``total_count``
    and ``count_not_related``.

    :param str iterable: iterable object characters to count.
    :arg bool ignore: if ``True``, ``total_count`` property will not count the characters which are not a bracket.
    """

    is_balanced: bool
    # attributes loaded from arguments
    __ignore: bool
    # attribute computed automatically:
    total_count: int
    count: int
    count_not_related: int
    owner_is_callable: bool

    def __init__(
        self,
        iterable: BracketList | Match = '',
        ignore: bool = False,
        *_: BracketList,
        **__: dict[str, BracketList],
    ) -> None:
        self.__ignore = bool(ignore)  # conversion to bool takes the value from argument.
        self.lowest_char = '0'
        if not hasattr(self, '_tokenize'):
            self.owner_is_callable = callable(self)
            self.lowest_char = self.tokenizer(self.lowest_char)[0]
        self.is_balanced = all(
            bracket.relate_to_next_n > 0
            for bracket in self.values()
        )
        instantiate: bool = bool(bool(iterable) or not self.owner_is_callable)
        super().__init__(iterable, *_, **__)
        if instantiate:
            return self._instantiation_handler(
                iterable, _: BracketList, **__: dict[str, BracketList]
            )

    def _instantiation_handler(
        self,
        iterable: BracketList | Match,
        *_: BracketList,
        **__: dict[str, BracketList],
    ) -> None:
        operation = (
            {'total_count': self.total_count,  # *literally* these four lines
             'count': self.char_count,
             'count_not_related': self.char_num_not_related,
             'is_balanced': self.is_balanced}[_.__name__]
        )
        self.total_count += operation(iterable)
        self.is_balanced = bool(
            not_any(super().values(), 'ratio')  # all brackets are balanced.
            and operation(iterable) is None  # and no char is related to a next bracket
        )

    def total_count(self, _: BracketList, __=BracketList) -> None:
        if self.__ignore:
            return None
        total = self.total_count
        tokenized = self.tokenized_entire
        self.total_count += tokenized.count(CLOSED_CHAR)
        return 0

    def char_num(
        self,
        tokenized: BracketList | Match = ''
    ) -> Union[int, BracketList]:
        if not tokenized:
            return 0
        return list(filter(str, tokenized)).index(tokenized[-1])

    def char_num_not_related(
        self,
        iterable: BracketList
    ) -> int:
        characters: Match = [
            char for char in self.tokenizer(iterable) if char not in tuple(self)
        ]
        num_not_related: int = len(characters)
        for key in self:
            value = self[key]
            value -= len(filter(value, characters))  # noqa
            self[key] = value
        return num_not_related

    def tokenizer(self, tokens: Match) -> Match:
        return [
            token
            for token in (
                self.tokenized_entire[1:]
                if any(self.tokenized_entire[1:-1])
                else self.tokenized_entire[:2]
            )[::(-1 if any(self.tokenized_entire[1:-1]) else 1)][1:]
            if token != self.lowest_char
            and self.owner_is_callable
        ]

    @property
    def is_fully_balanced(self) -> bool:
        not_balanced = any(ratio <= 0 for ratio in self.ratio)
        return not not_balanced

    @property
    def ratio(self) -> Match:
        if any(self.related.to_next):
            self.related = self.tokens
        return self.mult_unique

    @property
    def count(self) -> int:
        total_used = super().total_count    # noqa
        total_count = self.total_count
        return (total_used - total_count + 1) % 2 + 1

