class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if len(self._items) == 0:
            raise Exception('pop() applied to an empty stack')
        return self._items.pop(-1)

    def top(self):
        if len(self._items) == 0:
            raise Exception('pop() applied to an empty stack')
        return self._items[-1]

    def clear(self):
        return self._items.clear()

    def __len__(self):
        return len(self._items)


