def solve(s, t):
    if not s:
        return True
    # Find the indices of characters in s in order within t
    indices_in_t = []
    current_index = -1
    for char in s:
        found = False
        for i in range(current_index + 1, len(t)):
            if t[i] == char:
                indices_in_t.append(i)
                current_index = i
                found = True
                break
        if not found:
            return False
    # Check if the indices in t are in increasing order
    for i in range(1, len(indices_in_t)):
        if indices_in_t[i] <= indices_in_t[i - 1]:
            return False
    return True

def solve(s, t):
    import re
    # Check if s is empty or longer than t
    if not s or len(s) > len(t):
        return True if not s else False
    # Create a regular expression pattern to match the characters of s in order
    pattern = ''.join(f'({char})' for char in s)
    # Search for the pattern in t
    match = re.search(pattern, t)
    return bool(match)

