def solve(points, k):
    def distance_squared(point):
        return point[0] ** 2 + point[1] ** 2

    # Use a heap to keep track of the k smallest distances
    # We use negative distances because Python's heapq is a min-heap
    # and we want the smallest distances to be popped first
    heap = []
    for point in points:
        dist = distance_squared(point)
        if len(heap) < k:
            heapq.heappush(heap, (-dist, point))
        else:
            # If the current distance is smaller than the largest in the heap, replace it
            if dist < -heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (-dist, point))

    # Extract the points from the heap
    result = [point for (dist, point) in heap]
    return result

