def solve(points, k):
    # Use a max-heap of size k to keep track of the k smallest distances
    # Store tuples of (-distance_squared, x, y) to simulate a max-heap using min-heap
    heap = []
    for x, y in points:
        dist_sq = x * x + y * y
        if len(heap) < k:
            heapq.heappush(heap, (-dist_sq, x, y))
        else:
            # If current point is closer than the farthest in the heap, replace it
            if -heap[0][0] > dist_sq:
                heapq.heappop(heap)
                heapq.heappush(heap, (-dist_sq, x, y))
    # Extract the k closest points
    return [[x, y] for _, x, y in heap]

