def solve_satisfactory_meals(shops, initial_money, required_money):
    # Sort shops by bad item price in descending order, then by good item price in ascending order
    shops.sort(key=lambda x: (-x[0], x[1]))

    money = initial_money
    satisfactory_meals = 0
    for shop in shops:
        bad_item, good_item = shop
        if money >= bad_item:
            money -= bad_item
            satisfactory_meals += 1
        if money >= required_money:
            return satisfactory_meals
        if money >= good_item:
            money -= good_item
            satisfactory_meals += 1
        if money >= required_money:
            return satisfactory_meals
    return satisfactory_meals

