# in addition to the [pointX, pointY] pair. The points are stored in a min heap:
# here are its methods from Chapter 2:
class PriorityQueue:
    def __init__(self):
        self._elements = []

    def _bubble_up(self, index):
        # moves element at position index up a level in the heap (while it is smaller
        # than its parent node)
        parentIndex = (index - 1) // 2
        if parentIndex >= 0:
            toSwap = parentIndex
            if self._elements[index][1] < self._elements[parentIndex][1]:
                # swap with parent
                temp = self._elements[index]
                self._elements[index] = self._elements[parentIndex]
                self._elements[parentIndex] = temp

                self._bubble_up(parentIndex)

    def _bubble_down(self, index):
        # moves element at position index down a level in the heap (while it is less than
        # either of its children,
        childIndexL = 2 * index + 1
        childIndexR = 2 * index + 2
        if self._elements[childIndexL][1] >= 0.0 or (childIndexR < len(self._elements) and
                self._elements[childIndexR][1] >= 0.0):
            fillSlot = -1
            smallest = 10**20
            if childIndexL < len(self._elements) and self._elements[childIndexL][1] < smallest:
                fillSlot = childIndexL
                smallest = self._elements[childIndexL][1]
            if childIndexR < len(self._elements) and self._elements[childIndexR][1] < smallest:
                fillSlot = childIndexR
                smallest = self._elements[childIndexR][1]
            if fillSlot >= 0:
                # swap with smallest child
                fillValue = self._elements[index]
                self._elements[index] = self._elements[fillSlot]
                self._elements[fillSlot] = fillValue
                self._bubble_down(fillSlot)

    def push(self, item, priority):
        # adds item with given priority to the queue
        self._elements.append([item, priority])
        currentIndex = len(self._elements) - 1
        self._bubble_up(currentIndex)

    def pop(self):
        # removes the smallest item from the queue
        rootValue = self._elements[0]
        lastElement = self._elements.pop(len(self._elements) - 1)
        if self._elements != []:
            self._elements[0] = lastElement
            self._bubble_down(0)
        return rootValue

    def change_priority(self, item, priority):
        # updates the info of the left-most occurrence of the item in the queue
        for listIndex in range(len(self._elements)):
            if self._elements[listIndex][0] == item:
                self._elements[listIndex][1] = priority
                break

    def __len__(self):
        return len(self._elements)

    def __getitem__(self, index):
        return self._elements[index]

    def __setitem__(self, index, value):
        self._elements[index] = value

    def __delitem__(self, index):
        del self._elements[index]

