def solve(points, k):
    # Use a max-heap to keep track of the k smallest distances
    # Store the negative of the squared distance to simulate a max-heap
    heap = []
    for point in points:
        x, y = point
        dist_sq = x * x + y * y
        if len(heap) < k:
            heapq.heappush(heap, (-dist_sq, point))
        else:
            # If current point is closer than the farthest in the heap, replace
            if dist_sq < -heap[0][0]:
                heapq.heappushpop(heap, (-dist_sq, point))
    # Extract the points from the heap
    return [point for (dist, point) in heap]

