def solve(points, k):
    def get_key(point):
        return (point[0], point[1])

    def get_distance(point):
        return math.hypot(point[0], point[1])

    if k == 0:
        return []

    queue = deque()
    for i in range(min(k, len(points))):
        queue.append((get_distance(points[i]), get_key(points[i])))

    for i in range(min(k, len(points)), len(points)):
        dist, key = get_distance(points[i]), get_key(points[i])
        if dist < queue[-1][0]:
            queue.pop()
            queue.append((dist, key))

    result = []
    for _ in range(k):
        result.append(queue.popleft()[1])

    return result

