def merge_sorted_lists(a, b):
    merged = []
    i = j = 0

    # Combine the lists until one is exhausted
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    # If there are remaining elements in a, append them
    while i < len(a):
        merged.append(a[i])
        i += 1

    # If there are remaining elements in b, append them
    while j < len(b):
        merged.append(b[j])
        j += 1

    return merged

